sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float dotSize;
uniform float angle;
uniform float sharpness;
uniform float inkMode;
layout(color) uniform half4 inkColor;
layout(color) uniform half4 paperColor;
uniform float invert;
uniform float dotGain;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = size * 0.5;
    float a = radians(angle);
    float2 p = rot2(coord - ctr, -a) / dotSize;
    float2 cellC = floor(p) + 0.5;
    float2 srcPos = rot2(cellC * dotSize, a) + ctr;
    float4 sp = tex(srcPos);
    float3 ss = unp(sp);
    float l = luma(ss);
    if (invert > 0.5) l = 1.0 - l;
    float rad = sqrt(saturate(1.0 - l + dotGain)) * 0.72;
    float soft = mix(0.5, 0.02, sharpness);
    float m = 1.0 - smoothstep(rad - soft, rad + soft * 0.5, length(fract(p) - 0.5));
    float3 ink = inkMode < 0.5 ? float3(inkColor.rgb) : ss;
    float3 paper = inkMode < 0.5 ? float3(paperColor.rgb) : float3(1.0);
    float3 o = mix(paper, ink, m);
    return fin(c, float4(o * c.a, c.a), opacity);
}
